class Solution { int countSegment(string& word,int start,int end,int k){int answer=0,length=end-start;for(int kinds=1;kinds<=26&&kinds*k<=length;++kinds){int window=kinds*k,distinct=0,exact=0;array<int,26> frequency{};for(int right=start;right<end;++right){int added=word[right]-'a';if(frequency[added]==0)++distinct;if(frequency[added]==k)--exact;if(++frequency[added]==k)++exact;if(right-start>=window){int removed=word[right-window]-'a';if(frequency[removed]==k)--exact;if(--frequency[removed]==k)++exact;if(frequency[removed]==0)--distinct;}if(right-start+1>=window&&distinct==kinds&&exact==kinds)++answer;}}return answer;}public:int countCompleteSubstrings(string word,int k){int answer=0,start=0;for(int end=1;end<=(int)word.size();++end)if(end==(int)word.size()||abs(word[end]-word[end-1])>2){answer+=countSegment(word,start,end,k);start=end;}return answer;} };
